package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct {
	LrAcct      string
	LrPrincipal decimal.Decimal
	LrRate      decimal.Decimal
	LrYears     int64
}

var WsEofFlag string = "N"
var WsInterest decimal.Decimal = decimal.NewFromInt(0)
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsPrinEd string
var WsIntEd string
var WsTotalEd string

var LoanRecVar LoanRec

var loanFile *os.File
var loanScanner *bufio.Scanner

func formatNumericEdited(value decimal.Decimal, picture string) string {
	// Determine decimal places from picture
	dotIdx := strings.Index(picture, ".")
	decPlaces := 0
	if dotIdx >= 0 {
		decPlaces = len(picture) - dotIdx - 1
	}
	// Width is len(picture)
	width := len(picture)

	// Round/truncate value to decPlaces for display? MOVE to edited field: value is already fitted.
	// We need to format with exactly decPlaces decimals, truncating/padding as needed.
	// Use string representation.
	neg := value.Sign() < 0
	if neg {
		value = value.Neg()
	}
	// Ensure value has correct scale: we will get integer part and fractional part
	// Use StringFixed to get exactly decPlaces decimals
	sFixed := value.StringFixed(int32(decPlaces)) // e.g. "1234.56"
	// Split
	parts := strings.SplitN(sFixed, ".", 2)
	intPart := parts[0]
	fracPart := ""
	if decPlaces > 0 {
		if len(parts) > 1 {
			fracPart = parts[1]
		} else {
			fracPart = strings.Repeat("0", decPlaces)
		}
		// If intPart has minus? Already handled
	}

	// Count integer digit positions in picture (Z and 9 before dot)
	intPic := picture
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
	}
	// Number of digit slots in integer part
	intSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	// If integer digits more than slots, drop high-order digits
	if len(intPart) > intSlots {
		intPart = intPart[len(intPart)-intSlots:]
	}
	// Pad intPart with leading zeros to intSlots
	if len(intPart) < intSlots {
		intPart = strings.Repeat("0", intSlots-len(intPart)) + intPart
	}

	// Now build integer formatted section character by character
	// Map digit positions to picture positions
	// We need to walk picture int section left to right, consuming digits
	var intResult strings.Builder
	digitIdx := 0
	// For suppression: Z means suppress leading zeros
	// Commas inside suppressed zone become spaces
	// Determine up to which picture position suppression applies:
	// Suppression continues until we encounter a non-zero digit or we are at the last digit position
	// Actually Z suppression: leading zeros replaced with spaces; commas in suppressed region also spaces.
	// Find index of last 'Z'/'9' in intPic to know digit positions
	// Simpler: construct array of chars for int part, then apply Z logic.

	// Build list of positions that are digit placeholders
	type picChar struct {
		ch      rune
		isDigit bool
	}
	var picChars []rune = []rune(intPic)
	// We'll fill result same length as intPic
	intRes := make([]rune, len(picChars))
	// digitIdx walks intPart
	dIdx := 0
	for i, pc := range picChars {
		if pc == 'Z' || pc == '9' {
			intRes[i] = rune(intPart[dIdx])
			dIdx++
		} else {
			intRes[i] = pc // ',' etc
		}
	}
	// Apply Z suppression
	// Find last digit position index
	lastDigitPos := -1
	for i, pc := range picChars {
		if pc == 'Z' || pc == '9' {
			lastDigitPos = i
		}
	}
	suppress := true
	for i, pc := range picChars {
		if pc == 'Z' || pc == '9' {
			if suppress {
				if intRes[i] == '0' {
					// If this is the last digit position, do not suppress (show 0)
					if i == lastDigitPos {
						// keep '0', stop suppress
						suppress = false
					} else {
						intRes[i] = ' '
						// keep suppress true
					}
				} else {
					// non-zero digit, stop suppress
					suppress = false
				}
			} else {
				// already non-suppressed, keep digit as is
			}
		} else {
			// comma
			if suppress {
				intRes[i] = ' '
			} else {
				// keep comma
			}
		}
	}

	// Assemble final
	var final string
	if decPlaces > 0 {
		final = string(intRes) + "." + fracPart
	} else {
		final = string(intRes)
	}
	// Ensure width (should already be)
	if len(final) < width {
		final = strings.Repeat(" ", width-len(final)) + final
	}
	if len(final) > width {
		final = final[len(final)-width:]
	}
	_ = neg
	return final
}

func formatIntZeroPad(v int64, width int) string {
	s := fmt.Sprintf("%d", v)
	if len(s) > width {
		s = s[len(s)-width:]
	}
	if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	}
	return s
}

func padRight(s string, n int) string {
	if len(s) > n {
		return s[:n]
	}
	if len(s) < n {
		return s + strings.Repeat(" ", n-len(s))
	}
	return s
}

func parseLoanRec(line string) LoanRec {
	// pad with spaces to 21
	if len(line) < 21 {
		line = line + strings.Repeat(" ", 21-len(line))
	}
	if len(line) > 21 {
		line = line[:21]
	}
	acct := line[0:6]
	prinStr := line[6 : 6+9]
	rateStr := line[15 : 15+4]
	yearsStr := line[19 : 19+2]

	prinStr = strings.TrimSpace(prinStr)
	if prinStr == "" {
		prinStr = "0"
	}
	rateStr = strings.TrimSpace(rateStr)
	if rateStr == "" {
		rateStr = "0"
	}
	yearsStr = strings.TrimSpace(yearsStr)
	if yearsStr == "" {
		yearsStr = "0"
	}

	prinInt, _ := decimal.NewFromString(prinStr)
	// PIC 9(7)V99 => scale 2
	prinVal := decimal.New(prinInt.IntPart(), -2)

	rateInt, _ := decimal.NewFromString(rateStr)
	rateVal := decimal.New(rateInt.IntPart(), -2)

	var yearsVal int64
	fmt.Sscan(yearsStr, &yearsVal)

	return LoanRec{
		LrAcct:      acct,
		LrPrincipal: prinVal,
		LrRate:      rateVal,
		LrYears:     yearsVal,
	}
}

func main() {
	var err error
	loanFile, err = os.Open("input.dat")
	if err != nil {
		// If file not exists, treat as empty
		loanFile = nil
		loanScanner = bufio.NewScanner(strings.NewReader(""))
	} else {
		defer loanFile.Close()
		loanScanner = bufio.NewScanner(loanFile)
		// Allow long lines
		buf := make([]byte, 0, 64*1024)
		loanScanner.Buffer(buf, 1024*1024)
	}

	MAIN_PARA()
}

func MAIN_PARA() {
	// OPEN INPUT LOAN-FILE
	READ_PARA()
	for !INPUT_DONE() {
		PROCESS_PARA()
	}
	// CLOSE LOAN-FILE
	if loanFile != nil {
		loanFile.Close()
	}
	SUMMARY_PARA()
}

func INPUT_DONE() bool {
	return WsEofFlag == "Y"
}

func READ_PARA() {
	if loanScanner != nil && loanScanner.Scan() {
		line := loanScanner.Text()
		LoanRecVar = parseLoanRec(line)
	} else {
		WsEofFlag = "Y"
	}
}

func PROCESS_PARA() {
	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	// Use decimal arithmetic: (principal * rate * years / 100)
	// Avoid Div: Shift(-2) for /100
	tmp := LoanRecVar.LrPrincipal.Mul(LoanRecVar.LrRate).Mul(decimal.NewFromInt(LoanRecVar.LrYears)).Shift(-2)
	// ROUNDED to scale of WS-INTEREST => PIC 9(9)V99 scale 2
	wsInterestRounded := tmp.Round(2)
	// Store with truncation of high-order digits if overflow: keep low-order digits that fit
	// PIC 9(9)V99 => 11 digits total (9 int +2 dec) => max 999999999.99
	// Simulate overflow: keep low-order digits
	WsInterest = fitDecimal(wsInterestRounded, 9, 2)

	WsTotal = WsTotal.Add(WsInterest)
	// Simulate overflow for TOTAL: PIC 9(11)V99 => 11 int digits +2 dec
	WsTotal = fitDecimal(WsTotal, 11, 2)

	WsCount = WsCount + 1
	// fit count 9(5)
	WsCount = fitInt(WsCount, 5)

	WsPrinEd = formatNumericEdited(fitDecimal(LoanRecVar.LrPrincipal, 7, 2), "Z,ZZZ,ZZ9.99")
	WsIntEd = formatNumericEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")
	// DISPLAY LR-ACCT " " WS-PRIN-ED " " WS-INT-ED
	// LR-ACCT is PIC X(6)
	fmt.Printf("%s %s %s\n", padRight(LoanRecVar.LrAcct, 6), WsPrinEd, WsIntEd)

	READ_PARA()
}

func SUMMARY_PARA() {
	WsTotalEd = formatNumericEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	// WS-COUNT is PIC 9(5) zero-padded width 5
	countStr := formatIntZeroPad(WsCount, 5)
	fmt.Printf("RECORDS: %s\n", countStr)
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func fitDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// Keep only low-order digits that fit if overflow: total digits = intDigits+scale
	// If integer part exceeds intDigits, drop high-order digits
	neg := v.Sign() < 0
	if neg {
		v = v.Neg()
	}
	// Truncate/round already done; ensure scale
	v = v.Truncate(scale) // ensure not extra scale, but keep as is
	// Get coefficient and exponent: v = coeff *10^exp ; for scale 2, exp = -2
	// Simpler: convert to integer of smallest unit: v *10^scale
	mult := decimal.NewFromInt(1)
	for i := int32(0); i < scale; i++ {
		mult = mult.Mul(decimal.NewFromInt(10))
	}
	units := v.Mul(mult).Truncate(0) // integer units
	// units should be integer; compute modulus 10^(intDigits+scale)
	modExp := intDigits + int(scale)
	mod := decimal.NewFromInt(1)
	for i := 0; i < modExp; i++ {
		mod = mod.Mul(decimal.NewFromInt(10))
	}
	// keep low-order digits: units mod mod
	if units.Cmp(mod) >= 0 || units.Cmp(mod.Neg()) <= 0 {
		units = units.Mod(mod)
	}
	result := units.Div(mult)
	if neg {
		result = result.Neg()
	}
	return result
}

func fitInt(v int64, digits int) int64 {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if v >= mod || v < 0 {
		v = v % mod
		if v < 0 {
			v += mod
		}
	}
	return v
}

