	rateVal := decimal.New(rateInt.IntPart(), -2)

	yearsVal, _ := strconv.ParseInt(yearsStr, 10, 64)

	return LoanRec{
		LrAcct:      acct,
		LrPrincipal: prinVal,
		LrRate:      rateVal,
		LrYears:     yearsVal,
	}
}

func main() {
	var err error
	loanFile, err = os.Open("input.dat")
	if err != nil {
		loanFile = nil
		loanScanner = bufio.NewScanner(strings.NewReader(""))
	} else {
		defer loanFile.Close()
		loanScanner = bufio.NewScanner(loanFile)
		buf := make([]byte, 0, 64*1024)
		loanScanner.Buffer(buf, 1024*1024)
	}

	MAIN_PARA()
}

func MAIN_PARA() {
	READ_PARA()
	for !INPUT_DONE() {
		PROCESS_PARA()
	}
	if loanFile != nil {
		loanFile.Close()
	}
	SUMMARY_PARA()
}

func INPUT_DONE() bool {
	return WsEofFlag == "Y"
}

func READ_PARA() {
	if loanScanner != nil && loanScanner.Scan() {
		line := loanScanner.Text()
		LoanRecVar = parseLoanRec(line)
	} else {
		WsEofFlag = "Y"
	}
}

func PROCESS_PARA() {
	tmp := LoanRecVar.LrPrincipal.Mul(LoanRecVar.LrRate).Mul(decimal.NewFromInt(LoanRecVar.LrYears)).Shift(-2)
	wsInterestRounded := tmp.Round(2)
	WsInterest = fitDecimal(wsInterestRounded, 9, 2)

	WsTotal = WsTotal.Add(WsInterest)
	WsTotal = fitDecimal(WsTotal, 11, 2)

	WsCount = WsCount + 1
	WsCount = fitInt(WsCount, 5)

	WsPrinEd = formatNumericEdited(fitDecimal(LoanRecVar.LrPrincipal, 7, 2), "Z,ZZZ,ZZ9.99")
	WsIntEd = formatNumericEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s\n", padRight(LoanRecVar.LrAcct, 6), WsPrinEd, WsIntEd)

	READ_PARA()
}

func SUMMARY_PARA() {
	WsTotalEd = formatNumericEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := formatIntZeroPad(WsCount, 5)
	fmt.Printf("RECORDS: %s\n", countStr)
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func fitDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	neg := v.Sign() < 0
	if neg {
		v = v.Neg()
	}
	v = v.Truncate(scale)
	mult := decimal.NewFromInt(1)
	for i := int32(0); i < scale; i++ {
		mult = mult.Mul(decimal.NewFromInt(10))
	}
	units := v.Mul(mult).Truncate(0)
	modExp := intDigits + int(scale)
	mod := decimal.NewFromInt(1)
	for i := 0; i < modExp; i++ {
		mod = mod.Mul(decimal.NewFromInt(10))
	}
	if units.Cmp(mod) >= 0 || units.Cmp(mod.Neg()) <= 0 {
		units = units.Mod(mod)
	}
	result := units.Div(mult)
	if neg {
		result = result.Neg()
	}
	return result
}

func fitInt(v int64, digits int) int64 {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if v >= mod || v < 0 {
		v = v % mod
		if v < 0 {
			v += mod
		}
	}
	return v
}
